import pdfplumber
import pandas as pd
import json

def clean_currency(value):
    if isinstance(value, str):
        return int(value.replace(',', '').replace('$', ''))
    return value

def clean_float(value):
    if isinstance(value, str):
        return float(value)
    return value

def clean_int(value):
    if isinstance(value, str):
        return int(value)
    return value

def get_pdf_data(pdf_path):
    employees = {}
    with pdfplumber.open(pdf_path) as pdf:
        for i, page in enumerate(pdf.pages):
            table = page.extract_table()
            if not table:
                continue

            # Assume first row of first page is header
            start_row = 0
            if i == 0:
                header = table[0]
                if header[0] == "ID":
                    start_row = 1
            elif table[0][0] == "ID": # Handle repeated headers
                 start_row = 1

            for row in table[start_row:]:
                if not row or not row[0]: # Skip empty rows
                    continue

                # Headers: ID, First, Last, Dept, Position, Salary, Years, Location, Score
                emp_id = row[0]

                # Check for None values in row to avoid errors
                row = [r if r is not None else "" for r in row]

                record = {
                    "ID": emp_id,
                    "First": row[1],
                    "Last": row[2],
                    "Dept": row[3],
                    "Position": row[4],
                    "Salary": clean_currency(row[5]),
                    "Years": clean_int(row[6]),
                    "Location": row[7],
                    "Score": clean_float(row[8])
                }
                employees[emp_id] = record
    return employees

def get_excel_data(excel_path):
    df = pd.read_excel(excel_path)
    employees = {}
    for _, row in df.iterrows():
        emp_id = row['ID']
        record = {
            "ID": emp_id,
            "First": row['First'],
            "Last": row['Last'],
            "Dept": row['Dept'],
            "Position": row['Position'],
            "Salary": int(row['Salary']),
            "Years": int(row['Years']),
            "Location": row['Location'],
            "Score": float(row['Score'])
        }
        employees[emp_id] = record
    return employees

def compare_data(old_data, new_data):
    deleted_employees = []
    modified_employees = []

    # Check for deleted
    for emp_id in old_data:
        if emp_id not in new_data:
            deleted_employees.append(emp_id)

    # Check for modifications
    # Fields to compare
    fields = ["First", "Last", "Dept", "Position", "Salary", "Years", "Location", "Score"]

    # Sort IDs for consistent processing
    all_ids = sorted(list(set(old_data.keys()) | set(new_data.keys())))

    for emp_id in all_ids:
        if emp_id in old_data and emp_id in new_data:
            old_record = old_data[emp_id]
            new_record = new_data[emp_id]

            for field in fields:
                old_val = old_record[field]
                new_val = new_record[field]

                # Handle slight float mismatches or type differences if necessary
                # But our cleaning should handle it.

                if old_val != new_val:
                    modified_employees.append({
                        "id": emp_id,
                        "field": field,
                        "old_value": old_val,
                        "new_value": new_val
                    })

    return sorted(deleted_employees), modified_employees

def main():
    pdf_path = "/root/employees_backup.pdf"
    excel_path = "/root/employees_current.xlsx"
    output_path = "/root/diff_report.json"

    print("Reading PDF...")
    old_data = get_pdf_data(pdf_path)
    print(f"Loaded {len(old_data)} records from PDF.")

    print("Reading Excel...")
    new_data = get_excel_data(excel_path)
    print(f"Loaded {len(new_data)} records from Excel.")

    print("Comparing...")
    deleted, modified = compare_data(old_data, new_data)

    report = {
        "deleted_employees": deleted,
        "modified_employees": modified
    }

    print(f"Found {len(deleted)} deleted employees.")
    print(f"Found {len(modified)} modified records.")

    with open(output_path, 'w') as f:
        json.dump(report, f, indent=2)
    print(f"Report written to {output_path}")

if __name__ == "__main__":
    main()
